package com.bank.cicd.stages;

import com.bank.cicd.PipelineStage;
import com.bank.cicd.StageResult;

// Fetches the exact commit from version control.
public class SourceStage implements PipelineStage {
    public String name() { return "SOURCE"; }

    public StageResult run(String commitSha) {
        // In real life: git checkout the SHA. Here we just confirm it exists.
        boolean ok = commitSha != null && !commitSha.isBlank();
        return new StageResult(name(), ok,
                ok ? "Checked out commit " + commitSha : "No commit provided");
    }
}
