package com.bank.cicd;

import java.util.List;
import java.util.logging.Logger;

// Orchestrator: runs stages in order, stops on the first failure.
public class Pipeline {
    private static final Logger log = Logger.getLogger(Pipeline.class.getName());
    private final List<PipelineStage> stages;

    public Pipeline(List<PipelineStage> stages) {
        this.stages = stages;
    }

    public boolean execute(String commitSha) {
        log.info(() -> "=== Pipeline start for commit " + commitSha + " ===");
        for (PipelineStage stage : stages) {
            StageResult result = stage.run(commitSha);
            if (result.isSuccess()) {
                log.info(() -> "[PASS] " + result.getStageName() + " - " + result.getDetail());
            } else {
                log.severe("[FAIL] " + result.getStageName() + " - " + result.getDetail());
                log.severe("Pipeline halted. Promotion blocked.");
                return false;
            }
        }
        log.info("=== Pipeline SUCCESS - artifact promoted ===");
        return true;
    }
}
