package com.bank.cicd;

import com.bank.cicd.stages.*;
import java.util.List;
import java.util.logging.*;

public class PipelineDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<PipelineStage> stages = List.of(
                new SourceStage(), new BuildStage(), new TestStage(),
                new PackageStage(), new ScanStage(), new DeployStage(),
                new VerifyStage());
        Pipeline pipeline = new Pipeline(stages);

        // Healthy commit passes all stages.
        pipeline.execute("a1b2c3-healthy");

        // Commit with a failing test is stopped at the TEST stage.
        pipeline.execute("x9y8z7-bad-test");
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
